(()=>{'use strict';
const A=window.RepoAccount,slot=document.getElementById('sync-switches'),refresh=document.getElementById('sync-switches-refresh');let epoch=0,busy=false,loaded=0;
function node(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
async function load(force=false){if(!A.user?.admin||busy||!force&&Date.now()-loaded<60000)return;busy=true;refresh.disabled=true;const version=++epoch;slot.replaceChildren(node('p','small','Loading sync switches…'));try{const data=await A.request('/api/sync-log?action=sync-settings');if(version!==epoch||!A.user?.admin)return;slot.replaceChildren();for(const [index,row] of data.switches.entries()){const wrap=node('div','sync-switch-row'),label=node('label','sync-switch-label'),input=node('input');input.type='checkbox';input.checked=row.enabled;input.disabled=!row.available;input.setAttribute('aria-describedby','sync-switch-description-'+index);label.append(input,node('strong',null,row.label));const detail=node('p','small',row.description);detail.id='sync-switch-description-'+index;const message=node('p','small',row.available?row.enabled?'Enabled':'Disabled':'Unavailable: '+row.state);message.setAttribute('role','status');const link=node('a',null,'Workflow history');link.href=row.url;link.target='_blank';link.rel='noopener';wrap.append(label,detail,message,link);slot.append(wrap);input.onchange=async()=>{if(version!==epoch||!A.user?.admin)return;const enabled=input.checked,previous=row.enabled;input.disabled=true;message.textContent='Saving…';try{const result=await A.request('/api/sync-log?action=sync-settings',{method:'POST',body:JSON.stringify({id:row.id,enabled,expectedState:row.state})});if(version!==epoch||!A.user?.admin)return;row.state=result.saved.state;row.enabled=result.saved.enabled;input.checked=row.enabled;message.textContent=row.enabled?'Saved. Enabled for future triggers.':'Saved. Disabled for future triggers.'}catch(error){if(version!==epoch||!A.user?.admin)return;input.checked=previous;message.textContent=error.message+' Refresh switches to read the current state.'}finally{if(version===epoch&&A.user?.admin)input.disabled=!row.available}}}loaded=Date.now()}catch(error){if(version!==epoch||!A.user?.admin)return;slot.replaceChildren(node('p','small',error.message))}finally{busy=false;refresh.disabled=false}}
function account(){if(!A.user?.admin){epoch++;loaded=0;slot.replaceChildren();return}if(!document.getElementById('sync-panel').hidden)void load()}
refresh.onclick=()=>void load(true);window.RepoAdminSyncSwitches={load:()=>load()};window.addEventListener('reposhelf-account',account);account();
})();
